<?php
defined('BASEPATH') or exit('No direct script access allowed');
init_head();
$escape = static function ($value) { return html_escape((string)$value); };
$time = static function ($value) use ($timezone) {
    return (new DateTimeImmutable($value,new DateTimeZone('UTC')))->setTimezone(new DateTimeZone($timezone))->format('M j, g:i:s A');
};
$duration = static function ($ms) { $s=(int)floor($ms/1000); return sprintf('%dm %02ds',intdiv($s,60),$s%60); };
$link = static function (array $params) use ($date) { return admin_url('google_analytics/visitors').'?'.http_build_query(['date'=>$date]+$params); };
?>
<link rel="stylesheet" href="<?php echo module_dir_url('google_analytics','assets/css/visitor-dashboard.css'); ?>?v=1">
<div id="wrapper"><main class="content ga-visitors">
  <div class="panel_s"><div class="panel-body">
    <div class="gv-heading"><div><p class="gv-eyebrow">WEBSITE ACTIVITY · JUSTSMARTCHOICE.COM</p><h1>Live Visitors</h1><p>See visits as they happen and follow each session’s journey.</p></div><div><span class="gv-pulse"></span> Updates every 15 seconds <button type="button" id="gv-pause" class="btn btn-default btn-sm" aria-pressed="false">Pause updates</button></div></div>
    <form method="get" class="gv-filters"><div><label for="gv-date">Visit date</label><input id="gv-date" class="form-control" type="date" name="date" required value="<?php echo $escape($date); ?>" max="<?php echo $escape((new DateTimeImmutable('today',new DateTimeZone($timezone)))->format('Y-m-d')); ?>" min="<?php echo $escape((new DateTimeImmutable('today',new DateTimeZone($timezone)))->modify('-29 days')->format('Y-m-d')); ?>"></div><div><label for="gv-ip">IP address (optional)</label><input id="gv-ip" class="form-control" type="text" name="ip" value="<?php echo $escape($search); ?>" placeholder="Filter by an exact IP address" maxlength="45"></div><button class="btn btn-info">Apply</button><a href="<?php echo $escape(admin_url('google_analytics/visitors')); ?>" class="btn btn-default">Today</a><a href="<?php echo $escape(admin_url('google_analytics')); ?>" class="btn btn-default">Google Analytics overview</a></form>
    <p class="gv-note">Times shown in <?php echo $escape($timezone); ?>. Only visitors who allow Analytics are logged. IP addresses identify a network connection, not a person.</p>
    <?php echo form_open(admin_url('google_analytics/visitors'),['class'=>'gv-logging']); ?><input type="hidden" name="visitor_logging" value="<?php echo $logging_enabled?'0':'1'; ?>"><span>Website visitor logging: <strong><?php echo $logging_enabled?'On':'Paused'; ?></strong></span> <button class="btn btn-default btn-sm" type="submit"><?php echo $logging_enabled?'Pause logging':'Enable logging'; ?></button><?php echo form_close(); ?>
  </div></div>
  <div id="gv-results" aria-live="polite">
  <?php if ($error) { ?><div class="alert alert-danger"><?php echo $escape($error); ?></div><?php } elseif ($report) { $summary=$report['summary']; ?>
    <section class="gv-stats" aria-label="Visit totals">
      <?php foreach ([['Active now',$report['live'],'Seen in the last 45 seconds'],['Visitors',$summary['visitors'],'Distinct consenting browsers on this date'],['Visits',$summary['sessions'],'Sessions with pages viewed on this date'],['Page views',$summary['views'],'New page loads on this date'],['Avg. active time',$duration($summary['sessions']?$summary['active_ms']/$summary['sessions']:0),'Estimated foreground time per visit']] as $stat) { ?>
      <div class="panel_s"><div class="panel-body"><h2><?php echo $escape($stat[0]); ?></h2><strong><?php echo $escape($stat[1]); ?></strong><p><?php echo $escape($stat[2]); ?></p></div></div><?php } ?>
    </section>
    <?php if ($detail) { ?><section class="panel_s"><div class="panel-body"><div class="gv-heading"><h2>Visit timeline</h2><a class="btn btn-default btn-sm" href="<?php echo $escape($link([])); ?>">Close timeline</a></div><p><strong>IP:</strong> <?php echo $escape($detail['session']['ip_address']); ?> · <?php echo $escape($detail['session']['browser'].' / '.$detail['session']['device']); ?> · <strong>Total active time:</strong> <?php echo $escape($duration($detail['session']['active_ms'])); ?></p><div class="table-responsive"><table class="table table-striped"><thead><tr><th>Page viewed</th><th>Opened</th><th>Last activity</th><th>Active time</th></tr></thead><tbody><?php foreach($detail['pages'] as $page) { ?><tr><td><code><?php echo $escape($page['path']); ?></code></td><td><?php echo $escape($time($page['first_seen'])); ?></td><td><?php echo $escape($time($page['last_seen'])); ?></td><td><?php echo $escape($duration($page['active_ms'])); ?></td></tr><?php } ?></tbody></table></div><?php if($detail['truncated']) { ?><p>Showing the first 500 pages in this visit.</p><?php } ?></div></section><?php } ?>
    <section class="panel_s"><div class="panel-body"><div class="gv-heading"><h2>Visitor sessions</h2><span><?php echo $escape($date); ?> · Most recent first</span></div><div class="table-responsive"><table class="table table-hover"><thead><tr><th>Status</th><th>IP address</th><th>Browser / device</th><th>First seen</th><th>Last seen</th><th>Pages</th><th>Active time</th><th>Latest page</th><th></th></tr></thead><tbody>
      <?php if(!$report['sessions']) { ?><tr><td colspan="9" class="gv-empty"><h3>No matching visits yet</h3><p>Consenting visitors will appear here after opening a public website page. Earlier visits cannot be reconstructed.</p></td></tr><?php } ?>
      <?php foreach($report['sessions'] as $visit) { ?><tr><td><span class="gv-status <?php echo $visit['live']?'is-live':''; ?>"><?php echo $visit['live']?'Active':'Earlier'; ?></span></td><td><code><?php echo $escape($visit['ip_address']); ?></code></td><td><?php echo $escape($visit['browser'].' / '.$visit['device']); ?></td><td><?php echo $escape($time($visit['first_seen'])); ?></td><td><?php echo $escape($time($visit['last_seen'])); ?></td><td><?php echo (int)$visit['pages']; ?></td><td><?php echo $escape($duration($visit['active_ms'])); ?></td><td class="gv-path"><?php echo $escape($visit['current_path']); ?></td><td><a class="btn btn-default btn-sm" href="<?php echo $escape($link(['visit'=>$visit['id']])); ?>">View journey</a></td></tr><?php } ?>
    </tbody></table></div><?php if($report['next']) { ?><a class="btn btn-default" href="<?php echo $escape($link(['before'=>$report['next'],'ip'=>$search])); ?>">Older visits</a><?php } ?></div></section>
    <section class="panel_s"><div class="panel-body"><h2>Daily visitors</h2><p>14 days ending on the selected date. Browser counts are unique within each day.</p><div class="table-responsive"><table class="table table-striped gv-daily"><thead><tr><th>Date</th><th>Visitors</th><th>Page views</th></tr></thead><tbody><?php foreach(array_reverse($report['daily']) as $day) { ?><tr><td><a href="<?php echo $escape(admin_url('google_analytics/visitors').'?date='.$day['date']); ?>"><?php echo $escape($day['date']); ?></a></td><td><?php echo (int)$day['visitors']; ?></td><td><?php echo (int)$day['views']; ?></td></tr><?php } ?></tbody></table></div></div></section>
  <?php } ?>
  </div>
  <p class="gv-note">Detailed logs are retained for 30 days and visible only to administrators. A visit ends after 30 minutes without activity. Active time pauses when the page is hidden, unfocused, or idle for over one minute. Shared connections, VPNs, blocked scripts and declined consent affect totals. IPs and individual journeys stay in your database and are not sent to Google Analytics.</p>
</main></div>
